const live = typeof window !== "undefined";
if (!live || !document.fonts) return;
const root = this;
const lines = Array.from(root.querySelectorAll("[data-fit]"));
if (root.hasAttribute("data-fit")) lines.unshift(root);
const lists = Array.from(root.querySelectorAll("[data-fit-max]"));
if (root.hasAttribute("data-fit-max")) lists.unshift(root);
if (!lines.length && !lists.length) return;
const ctx = document.createElement("canvas").getContext("2d");
if (!ctx) return;
const ready = (cs) => document.fonts.check(`${cs.fontWeight} 16px ${cs.fontFamily}`);
const ems = (el, words) => {
	const cs = getComputedStyle(el);
	if (!ready(cs)) return 0;
	const size = parseFloat(cs.fontSize) || 16;
	const raw = String(words == null ? el.textContent : words).replace(/\s+/g, " ").trim();
	const set = cs.textTransform === "uppercase" ? raw.toUpperCase() : raw;
	ctx.font = `${cs.fontStyle} ${cs.fontWeight} 1000px ${cs.fontFamily}`;
	const tracking = (parseFloat(cs.letterSpacing) || 0) / size;
	return ctx.measureText(set).width / 1000 + tracking * Array.from(set).length;
};
const width = (el) => {
	const parts = Array.from(el.querySelectorAll("[data-fit-part]"));
	return parts.length ? ems(el, parts.map((part) => part.textContent.trim()).join(" ")) : ems(el);
};
const measure = () => {
	lines.forEach((el) => {
		const w = width(el);
		if (w > 0.5) el.style.setProperty("--w", w.toFixed(3));
	});
	lists.forEach((list) => {
		const items = Array.from(list.querySelectorAll("[data-fit-item]"));
		const w = items.length ? Math.max(...items.map((item) => ems(item))) : 0;
		if (w > 0.5) list.style.setProperty("--wmax", w.toFixed(3));
	});
};
let timer = 0;
const later = () => { clearTimeout(timer); timer = setTimeout(measure, 120); };
document.fonts.ready.then(measure).catch(() => {});
document.fonts.addEventListener("loadingdone", later);
